     1	//! Renderer implementation and utilities. The renderer is responsible for
     2	//! taking the internal screen state and turning into some output format,
     3	//! usually for a screen.
     4	//!
     5	//! The renderer is closely tied to the windowing system which usually
     6	//! has to prepare the window for the given renderer using system-specific
     7	//! APIs. The renderers in this package assume that the renderer is already
     8	//! setup (OpenGL has a context, Vulkan has a surface, etc.)
     9	
    10	const build_config = @import("build_config.zig");
    11	
    12	const cursor = @import("renderer/cursor.zig");
    13	const message = @import("renderer/message.zig");
    14	const size = @import("renderer/size.zig");
    15	pub const shadertoy = @import("renderer/shadertoy.zig");
    16	pub const Backend = @import("renderer/backend.zig").Backend;
    17	pub const GenericRenderer = @import("renderer/generic.zig").Renderer;
    18	pub const Metal = @import("renderer/Metal.zig");
    19	pub const OpenGL = @import("renderer/OpenGL.zig");
    20	pub const Options = @import("renderer/Options.zig");
    21	pub const Overlay = @import("renderer/Overlay.zig");
    22	pub const Thread = @import("renderer/Thread.zig");
    23	pub const State = @import("renderer/State.zig");
    24	pub const CursorStyle = cursor.Style;
    25	pub const Message = message.Message;
    26	pub const Size = size.Size;
    27	pub const Coordinate = size.Coordinate;
    28	pub const CellSize = size.CellSize;
    29	pub const ScreenSize = size.ScreenSize;
    30	pub const GridSize = size.GridSize;
    31	pub const Padding = size.Padding;
    32	pub const cursorStyle = cursor.style;
    33	pub const lib = @import("lib/main.zig");
    34	
    35	/// The implementation to use for the renderer. This is comptime chosen
    36	/// so that every build has exactly one renderer implementation.
    37	pub const Renderer = GenericRenderer(GraphicsAPI);
    38	
    39	const GraphicsAPI = switch (build_config.renderer) {
    40	    .metal => Metal,
    41	    .opengl => OpenGL,
    42	};
    43	
    44	/// The app-scoped render device from which surface renderers are created.
    45	pub const Device = GraphicsAPI.Device;
    46	
    47	/// The health status of a renderer. These must be shared across all
    48	/// renderers even if some states aren't reachable so that our API users
    49	/// can use the same enum for all renderers.
    50	pub const Health = enum(c_int) {
    51	    healthy,
    52	    unhealthy,
    53	
    54	    test "ghostty.h Health" {
    55	        try lib.checkGhosttyHEnum(Health, "GHOSTTY_RENDERER_HEALTH_");
    56	    }
    57	};
    58	
    59	test {
    60	    // Our comptime-chosen renderer
    61	    _ = Renderer;
    62	
    63	    _ = cursor;
    64	    _ = message;
    65	    _ = shadertoy;
    66	    _ = size;
    67	    _ = Thread;
    68	    _ = State;
    69	}
