   446	                alloc,
   447	                atlas,
   448	                index,
   449	                glyph_index,
   450	                render_opts,
   451	            );
   452	        },
   453	
   454	        else => return err,
   455	    };
   456	
   457	    // Cache and return
   458	    gop.value_ptr.* = .{
   459	        .glyph = glyph,
   460	        .presentation = p,
   461	    };
   462	
   463	    return gop.value_ptr.*;
   464	}
